create table if not exists public.crypto_release_manifests(
  id bigint generated by default as identity primary key,
  manifest_key text not null unique,
  build text not null,
  manifest jsonb not null,
  source_commit text not null,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  constraint crypto_release_manifests_key_chk check(manifest_key ~ '^[a-z0-9._-]{3,80}$'),
  constraint crypto_release_manifests_build_chk check(build ~ '^[0-9]{4,10}$'),
  constraint crypto_release_manifests_manifest_object_chk check(jsonb_typeof(manifest)='object')
);
create unique index if not exists crypto_release_manifests_one_active_build_idx on public.crypto_release_manifests(build) where active;

create table if not exists public.crypto_release_drift_observations(
  id bigint generated by default as identity primary key,
  manifest_id bigint not null references public.crypto_release_manifests(id) on delete restrict,
  source text not null default 'automation',
  repository_head_sha text,
  application_commit text not null,
  root_v78_sha text not null,
  pwa_cache text not null,
  edge_functions jsonb not null default '[]'::jsonb,
  assets jsonb not null default '[]'::jsonb,
  note text,
  observed_at timestamptz not null default now(),
  constraint crypto_release_drift_source_chk check(source in('automation','operator','release')),
  constraint crypto_release_drift_sha_chk check(application_commit ~ '^[0-9a-f]{40}$' and root_v78_sha ~ '^[0-9a-f]{40}$'),
  constraint crypto_release_drift_head_chk check(repository_head_sha is null or repository_head_sha ~ '^[0-9a-f]{40}$'),
  constraint crypto_release_drift_edge_array_chk check(jsonb_typeof(edge_functions)='array'),
  constraint crypto_release_drift_assets_array_chk check(jsonb_typeof(assets)='array'),
  constraint crypto_release_drift_note_chk check(note is null or char_length(note)<=500)
);
create index if not exists crypto_release_drift_manifest_time_idx on public.crypto_release_drift_observations(manifest_id,observed_at desc);

create table if not exists public.crypto_rollback_rehearsals(
  id bigint generated by default as identity primary key,
  manifest_id bigint not null references public.crypto_release_manifests(id) on delete restrict,
  candidate_checkpoint_id bigint references public.crypto_release_checkpoints(id) on delete set null,
  rollback_target_sha text not null,
  result text not null,
  metadata_only boolean not null default true,
  checks jsonb not null default '[]'::jsonb,
  note text,
  rehearsed_at timestamptz not null default now(),
  constraint crypto_rollback_target_sha_chk check(rollback_target_sha ~ '^[0-9a-f]{40}$'),
  constraint crypto_rollback_result_chk check(result in('passed','warning','failed')),
  constraint crypto_rollback_checks_array_chk check(jsonb_typeof(checks)='array'),
  constraint crypto_rollback_note_chk check(note is null or char_length(note)<=500)
);
create index if not exists crypto_rollback_rehearsals_manifest_time_idx on public.crypto_rollback_rehearsals(manifest_id,rehearsed_at desc);

alter table public.crypto_release_manifests enable row level security;
alter table public.crypto_release_drift_observations enable row level security;
alter table public.crypto_rollback_rehearsals enable row level security;

drop policy if exists crypto_release_manifests_service_only on public.crypto_release_manifests;
create policy crypto_release_manifests_service_only on public.crypto_release_manifests for all to service_role using(true) with check(true);
drop policy if exists crypto_release_drift_service_only on public.crypto_release_drift_observations;
create policy crypto_release_drift_service_only on public.crypto_release_drift_observations for all to service_role using(true) with check(true);
drop policy if exists crypto_rollback_rehearsals_service_only on public.crypto_rollback_rehearsals;
create policy crypto_rollback_rehearsals_service_only on public.crypto_rollback_rehearsals for all to service_role using(true) with check(true);

revoke all on public.crypto_release_manifests from public,anon,authenticated;
revoke all on public.crypto_release_drift_observations from public,anon,authenticated;
revoke all on public.crypto_rollback_rehearsals from public,anon,authenticated;
grant all on public.crypto_release_manifests to service_role;
grant all on public.crypto_release_drift_observations to service_role;
grant all on public.crypto_rollback_rehearsals to service_role;

